import sys
from collections import deque

def min_distance(c1, c2):
    d1 = abs(ord(c1) - ord(c2))
    d2 = 26 - d1
    return min(d1, d2)

def max_occurrences(N, M, K, S, T):
    def can_form_with_cost(limit):
        dp = [0] * (M + 1)
        for i in range(1, M + 1):
            cost = 0
            for j in range(N):
                if i - j - 1 < 0:
                    break
                cost += min_distance(S[j], T[i - j - 1])
                if cost > limit:
                    break
            if cost <= limit:
                dp[i] = max(dp[i], dp[i - N] + 1)
            dp[i] = max(dp[i], dp[i - 1])
        return dp[M]

    low, high = 0, K
    result = 0
    while low <= high:
        mid = (low + high) // 2
        if can_form_with_cost(mid) >= can_form_with_cost(mid + 1):
            result = can_form_with_cost(mid)
            high = mid - 1
        else:
            low = mid + 1
    return result

input = sys.stdin.read().split()
N = int(input[0])
M = int(input[1])
K = int(input[2])
S = input[3]
T = input[4]
print(max_occurrences(N, M, K, S, T))
